1	package contractsentinel
2	
3	import (
4		"encoding/json"
5		"strings"
6		"testing"
7	)
8	
9	// Marshal a config parsed through the standard entry point and resolve the
10	// same request against the original and the saved-and-reparsed config. The
11	// fix is that queryTransforms used to be tagged json:"-", so saving silently
12	// dropped every rule and a re-read stopped rewriting the query string.
13	func roundTripResolve(t *testing.T, cfg *Config, method, target string) (*Resolution, *Config) {
14		t.Helper()
15		out, err := json.Marshal(cfg)
16		if err != nil {
17			t.Fatalf("marshal: %v", err)
18		}
19		saved, f := ParseConfig(out)
20		if f != nil {
21			t.Fatalf("saved config rejected on re-read: %v\n%s", f, out)
22		}
23		before := resolveJSON(t, cfg, `{"method":"`+method+`","target":"`+target+`"}`)
24		after := resolveJSON(t, saved, `{"method":"`+method+`","target":"`+target+`"}`)
25		if before.RouteID != after.RouteID || before.UpstreamURL != after.UpstreamURL {
26			t.Fatalf("resolve changed after save/reload:\n before %+v\n after  %+v", before, after)
27		}
28		return after, saved
29	}
30	
31	func TestConfigMarshalPreservesQueryTransforms(t *testing.T) {
32		// Literal rule fields carry spaces, Chinese, '+' and raw '%'; they must
33		// be saved as literal strings, never query-encoded or -decoded.
34		src := `{"routes":[
35		  {"id":"plain","methods":["get"],"pathPrefix":"/a","upstream":"http://h1.example/base/"},
36		  {"id":"rich","methods":["GET","POST"],"pathPrefix":"/c","upstream":"http://h3.example/u",
37		   "queryTransforms":[
38		     {"op":"rename","name":"x","to":"b"},
39		     {"op":"set","name":"b","value":"9"},
40		     {"op":"rename","name":"a b","to":"中 文+"},
41		     {"op":"set","name":"%","value":"p c+%25"},
42		     {"op":"set","name":"dup","value":""},
43		     {"op":"remove","name":"flag"}
44		   ]}
45		]}`
46		cfg := mustConfig(t, src)
47		out, err := json.Marshal(cfg)
48		if err != nil {
49			t.Fatal(err)
50		}
51		doc := string(out)
52	
53		// Rules are present, in order, with their literal strings.
54		wantSequence := `"queryTransforms":[` +
55			`{"op":"rename","name":"x","to":"b"},` +
56			`{"op":"set","name":"b","value":"9"},` +
57			`{"op":"rename","name":"a b","to":"中 文+"},` +
58			`{"op":"set","name":"%","value":"p c+%25"},` +
59			`{"op":"set","name":"dup","value":""},` +
60			`{"op":"remove","name":"flag"}]`
61		if !strings.Contains(doc, wantSequence) {
62			t.Fatalf("rules not preserved verbatim and in order:\n%s", doc)
63		}
64		// remove must not carry value; rename must not carry value; set keeps the
65		// empty value. No null may appear anywhere (routes or rules).
66		if strings.Contains(doc, `"op":"remove","name":"flag","value"`) ||
67			strings.Contains(doc, `"op":"rename","name":"x","to":"b","value"`) {
68			t.Fatalf("op-specific field rules violated:\n%s", doc)
69		}
70		if strings.Contains(doc, "null") {
71			t.Fatalf("saved config contains null:\n%s", doc)
72		}
73		// Basic fields keep their literal spelling: method case, upstream slash.
74		if !strings.Contains(doc, `"methods":["get"]`) ||
75			!strings.Contains(doc, `"upstream":"http://h1.example/base/"`) {
76			t.Fatalf("basic fields not preserved:\n%s", doc)
77		}
78	
79		// Duplicate params, empty values, raw percent escapes, a chained
80		// rename-into-an-existing-name followed by set, and untouched fragments
81		// must resolve identically before and after the save.
82		target := "/c?keep=1&x=7&b=2&a+b=q&%25=raw&dup=1&dup=2&flag&keep=2&e="
83		after, saved := roundTripResolve(t, cfg, "GET", target)
84		if after.RouteID != "rich" {
85			t.Fatalf("routeId = %q, want rich", after.RouteID)
86		}
87		// Sanity-check the rewritten query itself: x renames onto the existing b
88		// and set merges both into one b=9 at x's position; dup collapses to an
89		// empty value; flag is gone; the rest keeps order and bytes.
90		wantQuery := "?keep=1&b=9&%E4%B8%AD%20%E6%96%87%2B=q&%25=p%20c%2B%2525&dup=&keep=2&e="
91		if !strings.HasSuffix(after.UpstreamURL, wantQuery) {
92			t.Fatalf("upstreamURL = %q, want suffix %q", after.UpstreamURL, wantQuery)
93		}
94	
95		// Route order and the rules' execution order are unchanged: a second
96		// request that only exercises later rules also resolves identically.
97		roundTripResolve(t, saved, "POST", "/c?flag&dup=z")
98		roundTripResolve(t, cfg, "get", "/a/x?untouched=a%41+%25")
99	}
100	
101	func TestConfigMarshalRulesFieldShape(t *testing.T) {
102		// Every rule re-reads with exactly the fields the input grammar allows.
103		cfg := mustConfig(t, `{"routes":[{"id":"r","methods":["*"],"pathPrefix":"/","upstream":"http://h",
104		  "queryTransforms":[
105		    {"op":"set","name":"a","value":""},
106		    {"op":"remove","name":"b"},
107		    {"op":"rename","name":"c","to":"d"}
108		  ]}]}`)
109		var doc struct {
110			Routes []struct {
111				Rules []map[string]json.RawMessage `json:"queryTransforms"`
112			} `json:"routes"`
113		}
114		if err := json.Unmarshal(mustMarshal(t, cfg), &doc); err != nil {
115			t.Fatal(err)
116		}
117		wantKeys := []map[string]bool{
118			{"op": true, "name": true, "value": true}, // set keeps value even when empty
119			{"op": true, "name": true},                // remove: no value, no to
120			{"op": true, "name": true, "to": true},    // rename: to, no value
121		}
122		for i, rule := range doc.Routes[0].Rules {
123			if len(rule) != len(wantKeys[i]) {
124				t.Fatalf("rule %d keys = %v, want %v", i, keysOf(rule), wantKeys[i])
125			}
126			for k := range wantKeys[i] {
127				if _, ok := rule[k]; !ok {
128					t.Fatalf("rule %d missing key %q: %v", i, k, rule)
129				}
130			}
131		}
132	}
133	
134	func TestConfigMarshalWithoutRulesOrRoutes(t *testing.T) {
135		// A route with no field and one with an explicit [] both save without a
136		// queryTransforms key (never null), and stay readable.
137		cfg := mustConfig(t, `{"routes":[
138		  {"id":"absent","methods":["*"],"pathPrefix":"/a","upstream":"http://h"},
139		  {"id":"empty","methods":["*"],"pathPrefix":"/b","upstream":"http://h","queryTransforms":[]}
140		]}`)
141		doc := string(mustMarshal(t, cfg))
142		if strings.Contains(doc, "queryTransforms") || strings.Contains(doc, "null") {
143			t.Fatalf("ruleless routes must omit the field without null:\n%s", doc)
144		}
145		roundTripResolve(t, cfg, "GET", "/a?a=1&b=")
146		roundTripResolve(t, cfg, "GET", "/b?%41=1&A=2")
147	
148		// An empty route array must save as [] rather than the rejected null.
149		empty := mustConfig(t, `{"routes":[]}`)
150		if got := string(mustMarshal(t, empty)); got != `{"routes":[]}` {
151			t.Fatalf("empty config = %s", got)
152		}
153	
154		// A nil Config (never parsed, but a plain json.Marshal call) likewise
155		// must not emit null.
156		var nilCfg Config
157		if got := string(mustMarshal(t, &nilCfg)); got != `{"routes":[]}` {
158			t.Fatalf("nil config = %s", got)
159		}
160	}
161	
162	func TestConfigMarshalIndentedStillResolves(t *testing.T) {
163		cfg := mustConfig(t, `{"routes":[{"id":"r","methods":["get"],"pathPrefix":"/p","upstream":"http://h/b",
164		  "queryTransforms":[{"op":"set","name":"q","value":"中文 +%"}]}]}`)
165		out, err := json.MarshalIndent(cfg, "", "  ")
166		if err != nil {
167			t.Fatal(err)
168		}
169		saved := mustConfig(t, string(out)) // indentation and key layout may vary
170		after := resolveJSON(t, saved, `{"method":"get","target":"/p/x?q=old"}`)
171		if after.RouteID != "r" || after.UpstreamURL != "http://h/b/x?q=%E4%B8%AD%E6%96%87%20%2B%25" {
172			t.Fatalf("indented round trip = %+v", after)
173		}
174	}
175	
176	func TestInvalidConfigsRemainRejectedAfterMarshalCode(t *testing.T) {
177		// The save path must not change read-side validation.
178		for _, src := range []string{
179			`{"routes":[{"id":"r","methods":["*"],"pathPrefix":"/","upstream":"http://h","queryTransforms":null}]}`,
180			`{"routes":[{"id":"r","methods":["*"],"pathPrefix":"/","upstream":"http://h","queryTransforms":[{"op":"remove","name":"a","value":"x"}]}]}`,
181			`{"routes":[{"id":"r","methods":["*"],"pathPrefix":"/","upstream":"http://h","queryTransforms":[{"op":"rename","name":"a","value":"x","to":"b"}]}]}`,
182			`{"routes":[{"id":"r","methods":["*"],"pathPrefix":"/","upstream":"http://h","queryTransforms":[{"op":"rename","name":"a","to":""}]}]}`,
183			`{"routes":null}`,
184		} {
185			if _, f := ParseConfig([]byte(src)); f == nil || f.Code != "invalid_config" {
186				t.Fatalf("expected invalid_config for %s, got %v", src, f)
187			}
188		}
189	}
190	
191	func mustMarshal(t *testing.T, v any) []byte {
192		t.Helper()
193		out, err := json.Marshal(v)
194		if err != nil {
195			t.Fatal(err)
196		}
197		return out
198	}
199	
200	func keysOf(m map[string]json.RawMessage) []string {
201		keys := make([]string, 0, len(m))
202		for k := range m {
203			keys = append(keys, k)
204		}
205		return keys
206	}
