232			}
233	
234			for _, req := range []struct{ method, target string }{
235				{"GET", "/a/b/x"},
236				{"POST", "/a/b/x"},
237				{"GET", "/a/other"},
238			} {
239				assertSameOutcome(t, req.method, req.target,
240					resolveFor(t, cfg, req.method, req.target),
241					resolveFor(t, saved, req.method, req.target))
